const { google } = require('googleapis');
const axios = require('axios');
const fs = require('fs');
const path = require('path');

const sleep = (ms) => new Promise(resolve => setTimeout(resolve, ms));

async function main() {
  try {
      console.log('🚀 Starting Gmail & Calendar Briefing...');

              // Parse Google credentials
                  const credentials = JSON.parse(process.env.GOOGLE_CREDENTIALS);
                      const auth = new google.auth.GoogleAuth({
                            credentials,
                                  scopes: [
                                          'https://www.googleapis.com/auth/gmail.readonly',
                                                  'https://www.googleapis.com/auth/calendar.readonly',
                                                        ],
                                                            });

                                                                const authClient = await auth.getClient();
                                                                    const gmail = google.gmail({ version: 'v1', auth: authClient });
                                                                        const calendar = google.calendar({ version: 'v3', auth: authClient });

                                                                            const briefing = {
                                                                                  timestamp: new Date().toISOString(),
                                                                                        gmail: {},
                                                                                              calendar: {},
                                                                                                    slack: {},
                                                                                                        };
                                                                                                        
                                                                                                            // Get unread emails since yesterday
                                                                                                                console.log('📧 Fetching unread emails...');
                                                                                                                    const yesterday = new Date(Date.now() - 24 * 60 * 60 * 1000);
                                                                                                                        const gmailQuery = `is:unread after:${yesterday.getFullYear()}/${String(yesterday.getMonth() + 1).padStart(2, '0')}/${String(yesterday.getDate()).padStart(2, '0')}`;
                                                                                                                            
                                                                                                                                const messagesRes = await gmail.users.messages.list({
                                                                                                                                      userId: 'me',
                                                                                                                                            q: gmailQuery,
                                                                                                                                                  maxResults: 10,
                                                                                                                                                      });
                                                                                                                                                      
                                                                                                                                                          briefing.gmail.unreadCount = messagesRes.data.resultSizeEstimate || 0;
                                                                                                                                                              briefing.gmail.unreadEmails = [];
                                                                                                                                                              
                                                                                                                                                                  if (messagesRes.data.messages) {
                                                                                                                                                                        for (const msg of messagesRes.data.messages.slice(0, 5)) {
                                                                                                                                                                                const fullMsg = await gmail.users.messages.get({
                                                                                                                                                                                          userId: 'me',
                                                                                                                                                                                                    id: msg.id,
                                                                                                                                                                                                              format: 'metadata',
                                                                                                                                                                                                                        metadataHeaders: ['From', 'Subject', 'Date'],
                                                                                                                                                                                                                                });
                                                                                                                                                                                                                                
                                                                                                                                                                                                                                        const headers = fullMsg.data.payload.headers;
                                                                                                                                                                                                                                                briefing.gmail.unreadEmails.push({
                                                                                                                                                                                                                                                          id: msg.id,
                                                                                                                                                                                                                                                                    from: headers.find(h => h.name === 'From')?.value || 'Unknown',
                                                                                                                                                                                                                                                                              subject: headers.find(h => h.name === 'Subject')?.value || '(no subject)',
                                                                                                                                                                                                                                                                                        date: headers.find(h => h.name === 'Date')?.value || 'Unknown',
                                                                                                                                                                                                                                                                                                });
                                                                                                                                                                                                                                                                                                      }
                                                                                                                                                                                                                                                                                                          }
                                                                                                                                                                                                                                                                                                          
                                                                                                                                                                                                                                                                                                              console.log(`Found ${briefing.gmail.unreadCount} unread emails`);
                                                                                                                                                                                                                                                                                                              
                                                                                                                                                                                                                                                                                                                  // Get today's calendar events
                                                                                                                                                                                                                                                                                                                      console.log('📅 Fetching today\'s calendar events...');
                                                                                                                                                                                                                                                                                                                          const now = new Date();
                                                                                                                                                                                                                                                                                                                              const startOfDay = new Date(now.getFullYear(), now.getMonth(), now.getDate());
                                                                                                                                                                                                                                                                                                                                  const endOfDay = new Date(startOfDay);
                                                                                                                                                                                                                                                                                                                                      endOfDay.setDate(endOfDay.getDate() + 1);
                                                                                                                                                                                                                                                                                                                                      
                                                                                                                                                                                                                                                                                                                                          const eventsRes = await calendar.events.list({
                                                                                                                                                                                                                                                                                                                                                calendarId: 'primary',
                                                                                                                                                                                                                                                                                                                                                      timeMin: startOfDay.toISOString(),
                                                                                                                                                                                                                                                                                                                                                            timeMax: endOfDay.toISOString(),
                                                                                                                                                                                                                                                                                                                                                                  singleEvents: true,
                                                                                                                                                                                                                                                                                                                                                                        orderBy: 'startTime',
                                                                                                                                                                                                                                                                                                                                                                            });
                                                                                                                                                                                                                                                                                                                                                                            
                                                                                                                                                                                                                                                                                                                                                                                briefing.calendar.events = [];
                                                                                                                                                                                                                                                                                                                                                                                    if (eventsRes.data.items) {
                                                                                                                                                                                                                                                                                                                                                                                          briefing.calendar.events = eventsRes.data.items.map(event => ({
                                                                                                                                                                                                                                                                                                                                                                                                  title: event.summary || '(no title)',
                                                                                                                                                                                                                                                                                                                                                                                                          start: event.start.dateTime || event.start.date,
                                                                                                                                                                                                                                                                                                                                                                                                                  end: event.end.dateTime || event.end.date,
                                                                                                                                                                                                                                                                                                                                                                                                                        }));
                                                                                                                                                                                                                                                                                                                                                                                                                            }
                                                                                                                                                                                                                                                                                                                                                                                                                            
                                                                                                                                                                                                                                                                                                                                                                                                                                console.log(`Found ${briefing.calendar.events.length} calendar events today`);
                                                                                                                                                                                                                                                                                                                                                                                                                                
                                                                                                                                                                                                                                                                                                                                                                                                                                    // Get Slack mentions and notify
                                                                                                                                                                                                                                                                                                                                                                                                                                        if (process.env.SLACK_BOT_TOKEN && process.env.SLACK_WEBHOOK) {
                                                                                                                                                                                                                                                                                                                                                                                                                                              console.log('💬 Fetching Slack mentions...');
                                                                                                                                                                                                                                                                                                                                                                                                                                                    try {
                                                                                                                                                                                                                                                                                                                                                                                                                                                            // You would implement Slack API calls here to get mentions
                                                                                                                                                                                                                                                                                                                                                                                                                                                                    briefing.slack.mentions = [];
                                                                                                                                                                                                                                                                                                                                                                                                                                                                          } catch (e) {
                                                                                                                                                                                                                                                                                                                                                                                                                                                                                  console.log('Note: Could not fetch Slack mentions:', e.message);
                                                                                                                                                                                                                                                                                                                                                                                                                                                                                        }
                                                                                                                                                                                                                                                                                                                                                                                                                                                                                            }
                                                                                                                                                                                                                                                                                                                                                                                                                                                                                            
                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                // Save briefing report
                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                    const reportsDir = path.join(process.cwd(), 'reports');
                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                        if (!fs.existsSync(reportsDir)) {
                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                              fs.mkdirSync(reportsDir, { recursive: true });
                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                  }
                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                  
                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                      fs.writeFileSync(
                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                            path.join(reportsDir, 'briefing.json'),
                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                  JSON.stringify(briefing, null, 2)
                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                      );
                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                      
                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                          console.log('✅ Briefing report saved to reports/briefing.json');
                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                          
                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                              // Notify Slack channel #daily-briefing
                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                  if (process.env.SLACK_WEBHOOK) {
                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                        console.log('📢 Sending Slack notification...');
                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                              const slackMessage = {
                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                      channel: '#daily-briefing',
                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                              username: 'Daily Briefing Bot',
                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                      attachments: [
                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                {
                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                            color: '#36a64f',
                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                        title: '📋 Daily Briefing',
                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                    text: `Good morning! Here\'s your briefing for ${new Date().toLocaleDateString()}.`,
                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                fields: [
                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                              {
                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                              title: '📧 Unread Emails',
                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                              value: `You have ${briefing.gmail.unreadCount} unread emails since yesterday.`,
                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                              short: false,
                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                            },
                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                          {
                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                          title: '📅 Today\'s Events',
                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                          value: briefing.calendar.events.length > 0
                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                            ? briefing.calendar.events
                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                  .map(e => `• ${e.title}`)
                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                        .join('\n')
                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                          : 'No events scheduled',
                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                          short: false,
                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                        },
                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                    ],
                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                              },
                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                      ],
                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                            };
                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                            
                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                  try {
                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                          await axios.post(process.env.SLACK_WEBHOOK, slackMessage);
                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                  console.log('✅ Slack notification sent');
                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                        } catch (e) {
                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                console.log('⚠️  Failed to send Slack notification:', e.message);
                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                      }
                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                          }
                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                          
                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                              console.log('✨ Daily briefing completed successfully!');
                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                } catch (error) {
                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                    console.error('❌ Error:', error.message);
                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                        process.exit(1);
                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                          }
                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                          }
                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                          
                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                          main();
